COPY public.notification_templates (code, name, enabled, zns_template_id, sms_content, sms_fallback, updated_by) FROM stdin;
ORDER_READY	Đồ uống sẵn sàng	t	\N	Coffeeholic: don {order_code} da san sang, moi {customer_name} den quay nhan.	t	\N
